#[cfg(test)]
mod tests {
    use super::*;
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    use tokio::net::TcpStream;

    #[tokio::test]
    async fn test_echo() {
        // Start listener on ephemeral port
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        tokio::spawn(async move {
            let (stream, _) = listener.accept().await.unwrap();
            Server::handle_echo(stream).await;
        });
        let mut client = TcpStream::connect(addr).await.unwrap();
        client.write_all(b"hello\n").await.unwrap();
        let mut buf = vec![0u8; 64];
        let n = client.read(&mut buf).await.unwrap();
        assert_eq!(&buf[..n], b"hello\n");
    }

    #[tokio::test]
    async fn test_broadcast() {
        let (tx, _) = broadcast::channel(16);
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let tx2 = tx.clone();
        tokio::spawn(async move {
            let (stream, _) = listener.accept().await.unwrap();
            Server::handle_broadcast(stream, tx2).await;
        });
        // Subscribe before client connects to get messages
        let mut rx = tx.subscribe();
        let mut client = TcpStream::connect(addr).await.unwrap();
        client.write_all(b"broadcast me\n").await.unwrap();
        // Give the server time to broadcast
        tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;
        // The message should have been broadcast
        match tokio::time::timeout(tokio::time::Duration::from_millis(100), rx.recv()).await {
            Ok(Ok(msg)) => assert_eq!(msg.trim(), "broadcast me"),
            _ => panic!("expected broadcast message"),
        }
    }
}
